interface.signature:
function useAccessibilityObserver() {
  // State (reactive to OS changes)
  prefersReducedMotion: boolean;
  prefersHighContrast: boolean;
  prefersDarkMode: boolean;
  // User overrides
  userSettings: { reducedMotion, highContrast, darkMode, largeText };
  // Actions
  setUserPreference: (key: string, value: boolean) => void;
  resetToOSDefaults: () => void;
  // Computed
  effectiveSettings: merged OS + user overrides;
}

function useDebugPanel() {
  isDebugPanelOpen: boolean;
  activeTab: 'audio' | 'sensor' | 'session' | 'pwa';
  toggleDebugPanel: () => void;
  getAudioGraphStatus: () => AudioDebugInfo;
  getSensorStatus: () => SensorDebugInfo;
  getSessionStatus: () => SessionDebugInfo;
  getServiceWorkerStatus: () => PWADebugInfo;
  copyDiagnostics: () => void;
}

mp3_8d_a11y_overrides: {
  reducedMotion: boolean | null;
  highContrast: boolean | null;
  darkMode: boolean | null;
  largeText: boolean | null;
}
